// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
/**
 * The article lead (model article-lead@1): the heading, the lead paragraph, the byline (the portrait, the
 * author, the date) and the cover picture. Axes: media (top: the cover over the copy, wide, start: the cover
 * before the copy from md up, end: after it).
 */
import { type ReactNode } from "react";
import { Block, Box, Container, Group, Stack, Text, Title } from "../compose";
import { MediaFrame } from "../components/media-frame";
import { cn } from "../utils";

export type ArticleLeadProps = {
  id: string;
  title: string;
  description?: string;
  image?: string;
  imageAlt: string;
  imageSrcset?: string;
  author: string;
  avatar?: string;
  date: string;
  level?: 1 | 2 | 3;
  padding?: "compact" | "standard" | "spacious";
  align?: "start" | "center" | "end";
  media?: "top" | "start" | "end";
  landmarkLabel?: string;
};

export function ArticleLead({
  id,
  title,
  description = "",
  image = "",
  imageAlt,
  imageSrcset = "",
  author,
  avatar = "",
  date,
  level = 2,
  padding = "standard",
  align = "start",
  media = "top",
  landmarkLabel,
}: ArticleLeadProps) {
  const titleId = id + "-title";
  const column =
    (align as string) === "center" ? "center"
    : (align as string) === "end" ? "end"
    : "start";
  const textAlign =
    (align as string) === "center" ? "text-center"
    : (align as string) === "end" ? "text-end"
    : "text-start";
  const frame =
    (media as string) === "top" ? "grid grid-cols-1 gap-12"
    : "grid grid-cols-1 items-center gap-12 md:grid-cols-2";
  const pictureClass =
    (media as string) === "start" ? "order-first"
    : (media as string) === "top" ? "order-first"
    : "";
  const ratio = ((media as string) === "top") ? "21/9" : "4/3";
  return (
    <Block
      tag="section"
      className={
        (padding as string) === "compact" ? "py-8 lg:py-16"
        : (padding as string) === "spacious" ? "py-24 lg:py-40"
        : "py-16 lg:py-32"
      }
      aria-labelledby={(landmarkLabel ? undefined : titleId)}
      aria-label={landmarkLabel}
      data-slot="article-lead"
    >
      <Container className="mx-auto w-full max-w-6xl px-4">
        <Box className={frame}>
          <Stack gap="6" align={column}>
            <Title as={level} size="4xl" weight="bold" className={cn("tracking-tight", textAlign)} id={titleId}>
              {title}
            </Title>
            {description ? (
              <Text size="lg" className={cn("text-muted-foreground", textAlign)}>
                {description}
              </Text>
            ) : null}
            <Group gap="4" align="center">
              <MediaFrame alt={author} src={avatar} ratio="1/1" className="size-10 shrink-0 rounded-full" />
              <Stack gap="0" align="start">
                <Text size="sm" weight="semibold">
                  {author}
                </Text>
                <Text size="sm" className={cn("text-muted-foreground", "")}>
                  {date}
                </Text>
              </Stack>
            </Group>
          </Stack>
          <MediaFrame alt={imageAlt} src={image} srcset={imageSrcset} ratio={ratio} className={pictureClass} />
        </Box>
      </Container>
    </Block>
  );
}
